let currentSection='home';const mediaQuery=window.matchMedia('(prefers-color-scheme: dark)');function showSection(id){try{if(!id||typeof id!=='string'){console.error('Invalid section ID provided');return;}
const sections=document.querySelectorAll('main section');sections.forEach((section)=>{section.classList.remove('active');section.setAttribute('aria-hidden','true');});const targetSection=document.getElementById(id);if(targetSection){targetSection.classList.add('active');targetSection.setAttribute('aria-hidden','false');updateNavigation(id);currentSection=id;const heading=targetSection.querySelector('h2');if(heading){heading.focus();}}else{console.error(`Section with ID '${id}' not found`);}}catch(error){console.error('Error showing section:',error);}}
function setupScrollToTop(){try{const scrollToTopBtn=document.getElementById('scrollToTopBtn');if(scrollToTopBtn){window.addEventListener('scroll',()=>{if(window.scrollY>300){scrollToTopBtn.classList.add('show');}else{scrollToTopBtn.classList.remove('show');}});scrollToTopBtn.addEventListener('click',()=>{window.scrollTo({top:0,behavior:'smooth'});});}}catch(error){console.error('Error setting up scroll-to-top button:',error);}}
function updateNavigation(activeId){try{const navLinks=document.querySelectorAll('nav a');navLinks.forEach((link)=>{const href=link.getAttribute('href');if(href===`#${activeId}`){link.setAttribute('aria-current','page');}else{link.removeAttribute('aria-current');}}); }catch(error){console.error('Error updating navigation:',error);}}
function applyTheme(mode){try{const body=document.body;const icon=document.getElementById('themeIcon');if(!body||!icon){console.error('Theme elements not found');return;}
body.classList.remove('light','dark');if(mode==='auto'){const prefersDark=mediaQuery.matches;body.classList.add(prefersDark?'dark':'light');icon.textContent='brightness_auto';icon.setAttribute('aria-label','Auto theme (follows system preference)');}else if(mode==='dark'){body.classList.add('dark');icon.textContent='dark_mode';icon.setAttribute('aria-label','Dark theme active');}else if(mode==='light'){body.classList.add('light');icon.textContent='light_mode';icon.setAttribute('aria-label','Light theme active');}else{console.warn(`Unknown theme mode: ${mode}`);applyTheme('auto');return;}
announceThemeChange(mode);}catch(error){console.error('Error applying theme:',error);}}
function setTheme(mode){try{if(!mode||typeof mode!=='string'){console.error('Invalid theme mode provided');return;}
localStorage.setItem('theme',mode);applyTheme(mode);}catch(error){console.error('Error setting theme:',error);}}
function initTheme(){try{const saved=localStorage.getItem('theme')||'auto';const themeSelect=document.getElementById('themeMode');if(themeSelect){themeSelect.value=saved;}
applyTheme(saved);}catch(error){console.error('Error initializing theme:',error);applyTheme('auto');}}
function announceThemeChange(mode){try{let liveRegion=document.getElementById('theme-announcement');if(!liveRegion){liveRegion=document.createElement('div');liveRegion.id='theme-announcement';liveRegion.setAttribute('aria-live','polite');liveRegion.setAttribute('aria-atomic','true');liveRegion.className='sr-only';document.body.appendChild(liveRegion);}
const messages={'auto':'Theme set to automatic (follows system preference)','light':'Light theme activated','dark':'Dark theme activated'};liveRegion.textContent=messages[mode]||'Theme changed';}catch(error){console.error('Error announcing theme change:',error);}}
function setupClickHandlers(){try{const navLinks=document.querySelectorAll('nav a');navLinks.forEach((link)=>{link.addEventListener('click',(event)=>{event.preventDefault();const sectionId=link.getAttribute('href')?.substring(1);if(sectionId){showSection(sectionId);}});});const themeSelect=document.getElementById('themeMode');if(themeSelect){themeSelect.addEventListener('change',()=>{setTheme(themeSelect.value);});}}catch(error){console.error('Error setting up click handlers:',error);}}
function setupKeyboardNavigation(){try{const navLinks=document.querySelectorAll('nav a');navLinks.forEach((link)=>{link.addEventListener('keydown',(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();link.click();}});});const themeSelect=document.getElementById('themeMode');if(themeSelect){themeSelect.addEventListener('keydown',(event)=>{if(event.key==='Enter'){setTheme(themeSelect.value);}});}}catch(error){console.error('Error setting up keyboard navigation:',error);}}
function setupSystemThemeListener(){try{mediaQuery.addListener((e)=>{const currentTheme=localStorage.getItem('theme')||'auto';if(currentTheme==='auto'){applyTheme('auto');}});}catch(error){console.error('Error setting up system theme listener:',error);}}
function setDynamicYear(){try{const yearElement=document.getElementById('year');if(yearElement){yearElement.textContent=new Date().getFullYear();}}catch(error){console.error('Error setting dynamic year:',error);}}
function initPerformanceMonitoring(){try{if('PerformanceObserver'in window){const observer=new PerformanceObserver((list)=>{const entries=list.getEntries();entries.forEach((entry)=>{if(entry.entryType==='navigation'){console.log('Page load time:',entry.loadEventEnd-entry.startTime,'ms');}});});observer.observe({entryTypes:['navigation']});}}catch(error){console.error('Error initializing performance monitoring:',error);}}
function setupVisibilityHandler(){try{document.addEventListener('visibilitychange',()=>{if(document.hidden){console.log('Page hidden - pausing operations');}else{console.log('Page visible - resuming operations');}});}catch(error){console.error('Error setting up visibility handler:',error);}}
function init(){try{console.log('Initializing Aurora Zone website...');setDynamicYear();initTheme();setupClickHandlers();setupKeyboardNavigation();setupSystemThemeListener();setupScrollToTop();initPerformanceMonitoring();setupVisibilityHandler();updateNavigation('home');console.log('Aurora Zone website initialized successfully!');}catch(error){console.error('Error during initialization:',error);}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}
if(typeof module!=='undefined'&&module.exports){module.exports={showSection,setTheme,applyTheme,initTheme};}